function makeKey(name: string, variant: string = 'default'): string {
  return (name.toLowerCase().trim() + ':' + (variant || 'default').toLowerCase().trim());
}

@Injectable({
  providedIn: 'root',
})
export class DgaIconRegistry {
  private registry = new Map<string, DgaIconDefinition>();

  constructor() {
    this.initDefaultRegistry();
  }

  private initDefaultRegistry(): void {
    // 1. Load SVG icons
    Object.entries(SVG_ICONS_DATA).forEach(([key, def]) => {
      this.registry.set(key, def as DgaIconDefinition);
    });

    // 2. Load DGA Font icons.
    // The full `dga-icon-*` class is always registered. The stripped alias
    // (e.g. `lock` from `dga-icon-lock`) is only registered when it does not
    // collide with an already-registered curated SVG icon, so the inline SVG
    // icons remain the ones resolved by their semantic names.
    FONT_ICON_NAMES.forEach(cls => {
      const name = cls.replace(/^dga-icon-/, '');
      this.registry.set(makeKey(cls, 'default'), {
        name: cls,
        variant: 'default',
        type: 'font',
        fontClass: cls
      });
      const strippedKey = makeKey(name, 'default');
      if (!this.registry.has(strippedKey)) {
        this.registry.set(strippedKey, {
          name,
          variant: 'default',
          type: 'font',
          fontClass: cls
        });
      }
    });
  }

  public registerIcon(definition: DgaIconDefinition): void {
    const key = makeKey(definition.name, definition.variant || 'default');
    this.registry.set(key, definition);
  }

  public registerIcons(definitions: DgaIconDefinition[]): void {
    definitions.forEach(def => this.registerIcon(def));
  }

  public getIcon(name: string, variant: string = 'default'): DgaIconDefinition | undefined {
    if (!name) return undefined;
    const cleanName = name.toLowerCase().trim();
    const cleanVariant = (variant || 'default').toLowerCase().trim();

    // 1. Direct match
    const exactKey = makeKey(cleanName, cleanVariant);
    if (this.registry.has(exactKey)) {
      return this.registry.get(exactKey);
    }

    // 2. Fallback to default variant for name
    const defaultKey = makeKey(cleanName, 'default');
    if (this.registry.has(defaultKey)) {
      const found = this.registry.get(defaultKey);
      if (found?.type === 'font') {
        const variantClass = this.resolveVariantClass(cleanVariant);
        return {
          ...found,
          variant: cleanVariant,
          fontClass: (found.fontClass + ' ' + variantClass).trim()
        };
      }
      return found;
    }

    // 3. Dynamic font icon fallback if name starts with "dga-icon-"
    if (cleanName.startsWith('dga-icon-')) {
      const variantClass = this.resolveVariantClass(cleanVariant);
      return {
        name: cleanName,
        variant: cleanVariant,
        type: 'font',
        fontClass: (cleanName + ' ' + variantClass).trim()
      };
    }

    // 4. Unknown icon fallback definition
    return {
      name: cleanName,
      variant: cleanVariant,
      type: 'svg',
      viewBox: '0 0 24 24',
      fill: 'none',
      stroke: 'currentColor',
      strokeWidth: '2',
      strokeLinecap: 'round',
      strokeLinejoin: 'round',
      svgHtml: '<circle cx="12" cy="12" r="10" /><path d="M12 8v4m0 4h.01" />'
    };
  }

  public hasIcon(name: string, variant: string = 'default'): boolean {
    const key = makeKey(name, variant);
    return this.registry.has(key) || this.registry.has(makeKey(name, 'default'));
  }

  public getAllIcons(): DgaIconDefinition[] {
    return Array.from(this.registry.values());
  }

  public resolveVariantClass(variant: string): string {
    switch (variant) {
      case 'stroke-rounded': return 'stroke rounded';
      case 'twotone-rounded': return 'twotone rounded';
      case 'duotone-rounded': return 'duotone rounded';
      case 'solid-rounded': return 'solid rounded';
      case 'bulk-rounded': return 'bulk rounded';
      case 'stroke-sharp': return 'stroke sharp';
      case 'solid-sharp': return 'solid sharp';
      case 'twotone': return 'twotone rounded';
      case 'duotone': return 'duotone rounded';
      case 'solid': return 'solid rounded';
      case 'bulk': return 'bulk rounded';
      case 'sharp': return 'stroke sharp';
      default: return '';
    }
  }
}
